import{_ as a,o as t,c as e,al as s,j as n}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"JSBSim 仿真","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sim_jsbsim/index.md","filePath":"zh/sim_jsbsim/index.md"}'),l={name:"zh/sim_jsbsim/index.md"};function h(o,i,p,r,d,c){return t(),e("div",null,[...i[0]||(i[0]=[s('<h1 id="jsbsim-仿真" tabindex="-1">JSBSim 仿真 <a class="header-anchor" href="#jsbsim-仿真" aria-label="Permalink to &quot;JSBSim 仿真&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This simulator is <a href="./../simulation/community_supported_simulators">community supported and maintained</a>. It may or may not work with current versions of PX4.</p><p>See <a href="./../dev_setup/dev_env">Toolchain Installation</a> for information about the environments and tools supported by the core development team.</p></div><p><a href="https://jsbsim.sourceforge.net/index.html" target="_blank" rel="noreferrer">JSBSim</a>是一款开源飞行仿真器（“飞行动力学模型”，FDM），可运行于 Microsoft Windows、Apple Macintosh、Linux、IRIX、Cygwin（Windows 上的 Unix 环境）等平台。 其功能包括完全可配置的空气动力学和推进系统，可对飞行器的复杂飞行动力学进行建模。 动力学模型还考虑了地球自转效应。</p><p>支持的飞行器：固定翼飞机、四旋翼飞行器、六旋翼飞行器</p>',4),n("lite-youtube",{videoid:"y5azVNmIVyw",title:"JSBSim with APX4 Software-In-The-Loop Simulation"},null,-1),s(`<div class="info custom-block"><p class="custom-block-title">INFO</p><p>See <a href="./../simulation/">Simulation</a> for general information about simulators, the simulation environment, and simulation configuration (e.g. supported vehicles).</p></div><h2 id="installation-ubuntu-linux" tabindex="-1">Installation (Ubuntu Linux) <a class="header-anchor" href="#installation-ubuntu-linux" aria-label="Permalink to &quot;Installation (Ubuntu Linux)&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These instructions were tested on Ubuntu 18.04</p></div><ol><li><p>Install the usual <a href="./../dev_setup/dev_env_linux_ubuntu">Development Environment on Ubuntu LTS / Debian Linux</a>.</p></li><li><p>从 发布页面 (<a href="https://github.com/JSBSim-Team/jsbsim/releases/tag/Linux" target="_blank" rel="noreferrer">https://github.com/JSBSim-Team/jsbsim/releases/tag/Linux</a>)安装JSBSim 发行版：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JSBSim-devel_1.1.0.dev1-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">release-numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.bionic.amd64.deb</span></span></code></pre></div></li><li><p>（可选）可使用 FlightGear 进行可视化。 如需安装 FlightGear，请参阅 FlightGear 安装说明(../sim_flightgear/index.md))。</p></li></ol><h2 id="running-the-simulation" tabindex="-1">Running the Simulation <a class="header-anchor" href="#running-the-simulation" aria-label="Permalink to &quot;Running the Simulation&quot;">​</a></h2><p>如下所示，可以通过 make 命令便捷地运行 JSBSim SITL 仿真：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsbsim</span></span></code></pre></div><p>这将同时运行 PX4 SITL 实例和 FlightGear 用户界面（用于可视化）。 如果希望在不启动 FlightGear 用户界面的情况下运行，可在 make 命令前添加 HEADLESS=1。</p><p>The supported vehicles and <code>make</code> commands are listed below (click on the links to see the vehicle images).</p><table tabindex="0"><thead><tr><th>Vehicle</th><th>通信</th></tr></thead><tbody><tr><td>Standard Plane</td><td><code>make px4_sitl jsbsim_rascal</code></td></tr><tr><td>Quadrotor</td><td><code>make px4_sitl jsbsim_quadrotor_x</code></td></tr><tr><td>六旋翼飞行器</td><td><code>make px4_sitl jsbsim_hexarotor_x</code></td></tr></tbody></table><p>The commands above launch a single vehicle with the full UI. <em>QGroundControl</em> should be able to automatically connect to the simulated vehicle.</p><h2 id="使用-ros-运行-jsbsim" tabindex="-1">使用 ROS 运行 JSBSim <a class="header-anchor" href="#使用-ros-运行-jsbsim" aria-label="Permalink to &quot;使用 ROS 运行 JSBSim&quot;">​</a></h2><p>要使用 ROS 运行 JSBSim：</p><ol><li><p>将 px4-jsbsim-bridge 软件包克隆到 catkin 工作空间中：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path_to_catkin_w</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/src</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Auterion/px4-jsbsim-bridge.git</span></span></code></pre></div></li><li><p>构建 jsbsim_bridge catkin 软件包：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catkin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsbsim_bridge</span></span></code></pre></div><p>::: 信息 必须已在工作空间中配置好 MAVROS（若尚未配置，请按照 MAVROS 安装指南操作）(../ros/mavros_installation.md)。</p></li></ol><p>:::</p><ol start="3"><li><p>然后，使用如下 launch 文件通过 ROS 启动 JSBSim：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunched</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsbsim_bridge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_jsbsim_bridge.launch</span></span></code></pre></div></li></ol><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://github.com/Auterion/px4-jsbsim-bridge" target="_blank" rel="noreferrer">px4-jsbsim-bridge readme</a></li></ul>`,18)])])}const m=a(l,[["render",h]]);export{k as __pageData,m as default};
